	}

{
		DisposableTransientService transientA, transientB;
		ScopedLambdaService scopedLambdaRoot;
		ContainerLambdaService containerLambda;
		ConstantService constantService;
		ForwardedService forwardedService;

		await using (var container = Container.Create(services =>
													  {
														  // Constant and Forwarding lambda registrations (container does not own disposal)
														  services.AddConstant(new ConstantService());
														  services.AddForwarding(_ => new ForwardedService());

														  // Transient and Shared registrations (container tracks and disposes)
														  services.AddTransient(_ => new DisposableTransientService());
														  services.AddShared(SharedWithin.Scope, _ => new ScopedLambdaService());
														  services.AddShared(SharedWithin.Container, _ => new ContainerLambdaService());
													  }))
		{
			// Resolve several transients
			transientA = await container.GetRequiredService<DisposableTransientService>();
			transientB = await container.GetRequiredService<DisposableTransientService>();
			scopedLambdaRoot = await container.GetRequiredService<ScopedLambdaService>();
			containerLambda = await container.GetRequiredService<ContainerLambdaService>();
			constantService = await container.GetRequiredService<ConstantService>();
			forwardedService = await container.GetRequiredService<ForwardedService>();

			// Root scope transient service (to show separate scope disposal)
			var scopeFactory = await container.GetRequiredService<IServiceScopeFactory>();
			ScopedLambdaService scopedLambdaInner;

			await using (var scope = scopeFactory.CreateScope())
			{
				var scopedProvider = scope.ServiceProvider;
				scopedLambdaInner = await scopedProvider.GetRequiredService<ScopedLambdaService>();
				Assert.IsFalse(scopedLambdaInner.Disposed);
			}

			Assert.IsTrue(scopedLambdaInner.Disposed); // Disposed by Container

			// Before disposal nothing is disposed yet
			Assert.IsFalse(containerLambda.Disposed);
			Assert.IsFalse(scopedLambdaRoot.Disposed);
			Assert.IsFalse(transientA.Disposed);
			Assert.IsFalse(transientB.Disposed);
			Assert.IsFalse(constantService.Disposed);
			Assert.IsFalse(forwardedService.Disposed);
		}

		Assert.IsTrue(containerLambda.Disposed);   // Disposed by Container
		Assert.IsTrue(scopedLambdaRoot.Disposed);  // Disposed by Container
		Assert.IsTrue(transientA.Disposed);        // Disposed by Container
		Assert.IsTrue(transientB.Disposed);        // Disposed by Container
		Assert.IsFalse(constantService.Disposed);  // Needed explicit Dispose since not disposed by Container
		Assert.IsFalse(forwardedService.Disposed); // Needed explicit Dispose since not disposed by Container

		constantService.Dispose();
		forwardedService.Dispose();

		Assert.IsTrue(constantService.Disposed);
		Assert.IsTrue(forwardedService.Disposed);
	}

{
	#region QuickStart

		await using var container = Container.Create(services =>
													 {
														 services.AddImplementation<Greeting>().For<IGreeting>();
													 });
		var greeting = await container.GetRequiredService<IGreeting>();
		Assert.AreEqual(expected: "Hello", greeting.Text);

	#endregion
	}

{
	#region SyncStart

		using var container = Container.Create(s => s.AddTypeSync<Greeting>());
		var greeting = container.GetRequiredServiceSync<Greeting>();
		Assert.AreEqual(expected: "Hello", greeting.Text);

	#endregion
	}

{
	#region SharedArguments

		await using var container = Container.Create(s =>
														 s.AddSharedTypeSync<Named, string>(SharedWithin.Container));
		var first = await container.GetRequiredService<Named, string>("alpha");
		var same = await container.GetRequiredService<Named, string>("alpha");
		var other = await container.GetRequiredService<Named, string>("beta");
		Assert.AreSame(first, same);
		Assert.AreNotSame(first, other);

	#endregion
	}

{
	#region MultiContract

		await using var container = Container.Create(s =>
														 s.AddSharedImplementationSync<Greeting>(SharedWithin.Container)
														  .For<IGreeting>()
														  .For<IMessage>());
		var greeting = await container.GetRequiredService<IGreeting>();
		var message = await container.GetRequiredService<IMessage>();
		Assert.AreSame<object>(greeting, message);

	#endregion
	}

{
	#region ScopeOverlay

		await using var container = Container.Create(s => s.AddConstant("root"));
		var scopes = await container.GetRequiredService<IServiceScopeFactory>();
		await using var child = scopes.CreateScope(s => s.AddConstant("child"));
		Assert.AreEqual(expected: "child", await child.ServiceProvider.GetRequiredService<string>());
		Assert.AreEqual(expected: "root", await container.GetRequiredService<string>());

	#endregion
	}

{
	#region RegistrationOptions

		await using var container = Container.Create(s =>
													 {
														 s.AddTypeSync<Greeting>();
														 s.AddTypeSync<Greeting>(Option.IfNotRegistered);
													 });
		var count = 0;

		await foreach (var greeting in container.GetServices<Greeting>())
		{
			count ++;
		}

		Assert.AreEqual(expected: 1, count);

	#endregion
	}

{
	#region CollectionsAreLazy

		var created = 0;
		await using var container = Container.Create(s =>
													 {
														 s.AddTransient<IGreeting>(_ =>
																				   {
																					   created ++;

																					   return new Greeting();
																				   });
														 s.AddTransient<IGreeting>(_ =>
																				   {
																					   created ++;

																					   return new Greeting();
																				   });
													 });
		var services = container.GetServices<IGreeting>();
		Assert.AreEqual(expected: 0, created);

		await foreach (var service in services)
		{
			Assert.AreEqual(expected: "Hello", service.Text);
		}

		Assert.AreEqual(expected: 2, created);

	#endregion
	}

{
	#region RequiredMembers

		await using var container = Container.Create(s =>
													 {
														 s.AddTypeSync<Greeting>();
														 s.AddTypeSync<Consumer>();
													 });
		var consumer = await container.GetRequiredService<Consumer>();
		Assert.AreEqual(expected: "Hello", consumer.Greeting.Text);
		Assert.IsNull(consumer.Optional);

	#endregion
	}

{
	#region InjectedFactories

		await using var container = Container.Create(s =>
													 {
														 s.AddTypeSync<Named, string>();
														 s.AddType<FactoryConsumer>();
													 });
		var consumer = await container.GetRequiredService<FactoryConsumer>();
		var item = await consumer.Create("created later");
		Assert.AreEqual(expected: "created later", item.Name);

	#endregion
	}

{
	#region FactoryProductOwnership

		await using var container = Container.Create(s => s.AddFactorySync<OwnedFactory>().For<Owned>(Option.DoNotDispose));
		var owned = await container.GetRequiredService<Owned>();
		Assert.IsFalse(owned.Disposed);
		owned.Dispose();
		Assert.IsTrue(owned.Disposed);

	#endregion
	}

{
	#region ModulesAreIdempotent

		await using var container = Container.Create(s =>
													 {
														 s.AddModule<GreetingModule>();
														 s.AddModule<GreetingModule>();
														 Assert.IsTrue(s.IsModuleRegistered<GreetingModule>());
													 });
		var count = 0;

		await foreach (var service in container.GetServices<IGreeting>())
		{
			count ++;
		}

		Assert.AreEqual(expected: 1, count);

	#endregion
	}

{
	#region Diagnostics

		using var writer = new StringWriter();
		using var debugger = new ServiceProviderDebugger(writer, leaveOpen: true);
		await using var container = Container.Create(s =>
													 {
														 s.AddConstant<IServiceProviderActions>(debugger);
														 s.AddTypeSync<Greeting>();
													 });
		await container.GetRequiredService<Greeting>();
		Assert.IsTrue(writer.ToString().Contains(nameof(Greeting)));

	#endregion
	}

{
	#region LowLevelRegistration

		ServiceCollection services =
		[
			new ServiceEntry(
				TypeKey.ServiceKey<Named, string>(), InstanceScope.Transient,
				new Func<IServiceProvider, string, Named>((_, name) => new Named(name)))
		];
		await using var container = new Container(services);
		var value = await container.GetRequiredService<Named, string>("explicit");
		Assert.AreEqual(expected: "explicit", value.Name);

	#endregion
	}

{
	#region DecoratorEnumeration

		await using var container = Container.Create(s =>
													 {
														 s.AddConstant("core");
														 s.AddTransientDecorator<string>((_, inner) => "[" + inner + "]");
													 });
		var values = new List<string>();

		await foreach (var value in container.GetServices<string>())
		{
			values.Add(value);
		}

		CollectionAssert.AreEqual(new[] { "core", "[core]" }, values);
		Assert.AreEqual(expected: "[core]", await container.GetRequiredService<string>());

	#endregion
	}

{
		using var container = Container.Create(s => s.AddConstant(new ValueTask<string>("ready")));
		Assert.ThrowsExactly<DependencyInjectionException>(() => container.GetRequiredServiceSync<string>());
	}

{
		using var container = Container.Create(s => s.AddTypeSync<Prepared>());
		Assert.ThrowsExactly<DependencyInjectionException>(() => container.GetRequiredServiceSync<Prepared>());
	}

{
		await using var container = Container.Create(_ => { });
		var factory = await container.GetRequiredService<IServiceScopeFactory>();
		await using var plain = factory.CreateScope();
		await using var configured = factory.CreateScope(_ => { });
		Assert.IsNull(plain.ServiceProvider.InitializationHandler);
		Assert.IsNotNull(configured.ServiceProvider.InitializationHandler);
	}

{
		await using var container = Container.Create(s =>
													 {
														 s.AddConstant("root");
														 s.AddSharedTypeSync<Named>(SharedWithin.Container);
													 });
		var factory = await container.GetRequiredService<IServiceScopeFactory>();
		await using var child = factory.CreateScope(s => s.AddConstant("child"));
		var first = await child.ServiceProvider.GetRequiredService<Named>();
		var root = await container.GetRequiredService<Named>();
		Assert.AreSame(first, root);
		Assert.AreEqual(expected: "child", root.Name);
	}

{
		await using var container = Container.Create(s => s.AddTypeSync<Pair, int, int>());
		var pair = await container.GetRequiredService<Pair, int, int>(arg1: 3, arg2: 7);
		Assert.AreEqual(expected: 3, pair.First);
		Assert.AreEqual(expected: 3, pair.Second);
	}

{
		using var output = new StringWriter();
		await DocumentationJobs.Run(output);
		Assert.AreEqual(
			string.Join(
				Environment.NewLine,
				"Session ready", "Starting job", "Processed report", "Finished job", "Session disposed", "Scope finished", ""), output.ToString());
	}

{
		await using var container = Container.Create(s =>
													 {
														 s.AddType<DepService>();      // transient dependency
														 s.AddType<ConsumerService>(); // consumes factory for DepService

														 s.AddSharedType<SharedDepService>(SharedWithin.Container); // shared dependency
														 s.AddType<SharedConsumerService>();                        // consumes factory for SharedDepService
													 });

		var consumer = await container.GetRequiredService<ConsumerService>();
		var dep1 = await consumer.GetDependencyAsync();
		var dep2 = await consumer.GetDependencyAsync();
		Assert.IsNotNull(dep1);
		Assert.IsNotNull(dep2);
		Assert.AreNotEqual(dep1.Id, dep2.Id); // transient -> different instances

		var sharedConsumer = await container.GetRequiredService<SharedConsumerService>();
		var shared1 = await sharedConsumer.GetDependencyAsync();
		var shared2 = await sharedConsumer.GetDependencyAsync();
		Assert.IsNotNull(shared1);
		Assert.IsNotNull(shared2);
		Assert.AreEqual(shared1.Id, shared2.Id); // singleton -> same instance
	}

{
		await using var container = Container.Create(services =>
													 {
														 services.AddFactory<MessageFactory>().For<IMessageProvider>();
														 services.AddFactory<SumCalculatorFactory>().For<ISumCalculator, int, int>();
													 });

		var provider = await container.GetRequiredService<IMessageProvider>();
		Assert.AreEqual(expected: "Hello", provider.Message);

		var calc = await container.GetRequiredService<ISumCalculator, int, int>(arg1: 3, arg2: 4);
		Assert.AreEqual(expected: 7, calc.Result);
	}

{
		await using var container = Container.Create(services =>
													 {
														 // Open generic registration
														 services.AddImplementation<Log<Any>>().For<ILog<Any>>();
													 });

		var alphaLogger = await container.GetRequiredService<ILog<Alpha>>();
		var betaLogger = await container.GetRequiredService<ILog<Beta>>();
		var gammaLogger = await container.GetRequiredService<ILog<Gamma>>();

		Assert.AreEqual(expected: "Alpha", alphaLogger.Category);
		Assert.AreEqual(expected: "Beta", betaLogger.Category);
		Assert.AreEqual(expected: "Gamma", gammaLogger.Category);
		Assert.AreEqual(expected: "Alpha: message", alphaLogger.Format("message"));
		Assert.AreEqual(expected: "Beta: test", betaLogger.Format("test"));
		Assert.AreEqual(expected: "Gamma: ping", gammaLogger.Format("ping"));
	}

{
		await using var container = Container.Create(services =>
													 {
														 services.AddType<TransientService>();
														 services.AddSharedType<ScopedService>(SharedWithin.Scope);
														 services.AddSharedType<SingletonService>(SharedWithin.Container);
													 });

		// Root container resolutions
		var transientA = await container.GetRequiredService<TransientService>();
		var transientB = await container.GetRequiredService<TransientService>();
		var scopedRootA = await container.GetRequiredService<ScopedService>();
		var scopedRootB = await container.GetRequiredService<ScopedService>();
		var singletonRootA = await container.GetRequiredService<SingletonService>();
		var singletonRootB = await container.GetRequiredService<SingletonService>();

		// Create child scope
		var scopeFactory = await container.GetRequiredService<IServiceScopeFactory>();
		await using var scope = scopeFactory.CreateScope();
		var scopedProvider = scope.ServiceProvider;

		var transientScopeA = await scopedProvider.GetRequiredService<TransientService>();
		var transientScopeB = await scopedProvider.GetRequiredService<TransientService>();
		var scopedChildA = await scopedProvider.GetRequiredService<ScopedService>();
		var scopedChildB = await scopedProvider.GetRequiredService<ScopedService>();
		var singletonChildA = await scopedProvider.GetRequiredService<SingletonService>();
		var singletonChildB = await scopedProvider.GetRequiredService<SingletonService>();

		// Transient: always different
		Assert.AreNotSame(transientA, transientB);
		Assert.AreNotSame(transientScopeA, transientScopeB);
		Assert.AreNotSame(transientA, transientScopeA);

		// Scoped: same within same provider, different across root and child scope
		Assert.AreSame(scopedRootA, scopedRootB);
		Assert.AreSame(scopedChildA, scopedChildB);
		Assert.AreNotSame(scopedRootA, scopedChildA);

		// Singleton (container): same across all resolutions and scopes
		Assert.AreSame(singletonRootA, singletonRootB);
		Assert.AreSame(singletonChildA, singletonChildB);
		Assert.AreSame(singletonRootA, singletonChildA);
	}

{
		await using var container = Container.Create(services =>
													 {
														 // Register two implementations for the same interface
														 services.AddImplementation<AlphaProcessor>().For<IProcessor>();
														 services.AddImplementation<BetaProcessor>().For<IProcessor>();

														 // Register three argument-based services (same concrete type, same argument type)
														 services.AddType<ValueTaggedService, int>();
														 services.AddType<ValueTaggedService, int>();
														 services.AddType<ValueTaggedService, int>();
													 });

		// Enumerate all IProcessor instances
		var processorIds = new List<string>();

		await foreach (var p in container.GetServices<IProcessor>())
		{
			processorIds.Add(p.Id);
